// MARK: - Perf-path regression tests (Huffman table, PNG unfilter, Terrarium decode)

/// Deterministic skewed payload: symbol k appears fib(k) times, shuffled by an LCG. Produces a dynamic
/// Huffman block with literal codes longer than 9 bits (exercises the lookup-table slow-path fallback).
private func skewedPayload() -> [UInt8] {
    var syms: [UInt8] = []
    var a = 1, b = 1
    for k in 0..<17 {
        syms += [UInt8](repeating: UInt8(k * 7 + 3), count: a)
        (a, b) = (b, a + b)
    }
    var state: UInt32 = 12345
    func lcg() -> Int { state = (state &* 1103515245 &+ 12345) & 0x7fffffff; return Int(state) }
    var i = syms.count - 1
    while i > 0 { let j = lcg() % (i + 1); syms.swapAt(i, j); i -= 1 }
    return syms
}

