    @Test func pngFilters3And4RoundTrip() throws {
        // Rows use filters 3,4,1,4,3,2 (average, Paeth, sub, Paeth, average, up).
        let img = try PNGDecoder.decode(Self.filterPNG)
        #expect(img.width == 7 && img.height == 6 && img.channels == 3)
        #expect(img.pixels == Self.filterPixels)
    }

    @Test func terrariumMatchesDoubleFormula() throws {
        let png = try PNGDecoder.decode(Self.filterPNG)
        let grid = try Terrarium.decode(png: Self.filterPNG)
        for i in 0..<(png.width * png.height) {
            let p = i * png.channels
            let r = Double(png.pixels[p]), g = Double(png.pixels[p + 1]), b = Double(png.pixels[p + 2])
            #expect(grid.samples[i] == Float(r * 256 + g + b / 256 - 32_768))
        }
    }
